#include <iostream>
#include <cstdio>
using namespace std;

// Little's Law: throughput = concurrency / latency (latency in seconds).
double throughputFn(double concurrency, double latencySeconds) {
    return concurrency / latencySeconds;
}

// Rearranged: concurrency = throughput * latency.
double concurrencyInFlight(double throughputPerSecond, double latencySeconds) {
    return throughputPerSecond * latencySeconds;
}

int main() {
    double example1Throughput = throughputFn(100, 0.020);
    printf("100 concurrent requests at 20ms each: %.0f req/s\n", example1Throughput);

    double queueLatencySeconds = 30.0;
    double sustainedThroughput = 10000;
    double inFlight = concurrencyInFlight(sustainedThroughput, queueLatencySeconds);
    printf("10,000 req/s sustained with 30s latency implies %.0f requests in flight at once\n", inFlight);

    // Doubling throughput while holding latency fixed doubles required concurrency too.
    double doubledThroughput = sustainedThroughput * 2;
    double inFlightAtDoubled = concurrencyInFlight(doubledThroughput, queueLatencySeconds);
    printf("Doubling that throughput to %.0f req/s at the same latency needs %.0f requests in flight\n", doubledThroughput, inFlightAtDoubled);

    return 0;
}
